function Login({ onLogin, onReset, busy, error }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [resetBusy, setResetBusy] = useState(false);
  const [resetMessage, setResetMessage] = useState("");
  return <main className="login-page"><form className="login-card" onSubmit={(e) => { e.preventDefault(); onLogin(username, password); }}>
    <img className="login-logo" src="./imagens/logo-oficial-rr.svg" alt="R&R Figueredo Transportes" />
    <h1>TELA DE LOGIN</h1>
    <label htmlFor="login-username">Usuário</label><input id="login-username" value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" placeholder="Digite seu usuário" required />
    <label htmlFor="login-password">Senha</label><input id="login-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" placeholder="Digite sua senha" required />
    {error && <p className="error-message" role="alert">{error}</p>}
    <button className="primary-button login-submit" type="submit" disabled={busy || (!supabase && !demoMode)}>{busy ? "Entrando…" : "Entrar"}</button>
    <button className="secondary-button login-submit" type="button" disabled={busy || resetBusy || !supabase} onClick={async () => {
      setResetMessage("");
      setResetBusy(true);
      try {
        await onReset(username);
        setResetMessage("Se a solicitação for aceita, você receberá um e-mail. Confira também a pasta de spam.");
      } catch (resetError) {
        setResetMessage(resetError?.message || "Não foi possível solicitar a recuperação de senha.");
      } finally { setResetBusy(false); }
    }}>{resetBusy ? "Solicitando…" : "Esqueci minha senha"}</button>
    {resetMessage && <p className="reset-message" role="status">{resetMessage}</p>}
    {!supabase && !demoMode && <p className="error-message">Configuração do Supabase não encontrada. Confira banco-de-dados/supabase/app-config.js.</p>}
    <small className="muted login-note">Acesso protegido pelo Supabase.</small>
  </form></main>;
}

css:
/* Login: fundo cinza claro, cartão escuro e espaçamento ampliado.
   Escopo limitado à tela de autenticação; não altera outros formulários. */
.login-page {
  background: #e5e5e5;
  padding: 21px 12px;
}
.login-page .login-card {
  width: min(100%, 414px);
  padding: 27px 25px 30px;
  border: 1px solid #34383d;
  border-radius: 18px;
  background: #202123;
  color: #fff;
  box-shadow: 0 16px 44px #00000024;
}
.login-page .login-card .login-logo {
  box-sizing: border-box;
  width: min(180px, 100%);
  height: 136px;
  object-fit: cover;
  margin: 0 auto 17px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.login-page .login-card h1 {
  margin: 0 0 37px;
  color: #fff;
  font-size: 25px;
  text-align: center;
}
.login-page .login-card label {
  margin: 0 0 7px;
  color: #fff;
  font-size: 14px;
}
.login-page .login-card input {
  min-height: 48px;
  margin: 0 0 24px;
  padding: 10px 12px;
  border: 1px solid #77818d;
  border-radius: 9px;
  background: #2c2e32;
  color: #fff;
}
.login-page .login-card input::placeholder { color: #b4bdc9; }
.login-page .login-card input:focus {
  outline: 2px solid #a4b2c4;
  outline-offset: 1px;
}
.login-page .login-card .login-submit {
  min-height: 46px;
  margin: 0 0 15px;
  font-size: 14px;
}
.login-page .login-card .login-submit.primary-button {
  background: #145746;
  color: #fff;
}
.login-page .login-card .login-submit.primary-button:hover { background: #1b6954; }
.login-page .login-card .login-submit.secondary-button {
  border: 1px solid #818a95;
  background: transparent;
  color: #fff;
}
.login-page .login-card .login-submit.secondary-button:hover { background: #34383d; }
.login-page .login-card .login-note {
  margin-top: 13px;
  color: #b4bdc9;
}
.login-page .login-card .reset-message { color: #d5e6e0; }
@media (max-width: 520px) {
  .login-page .login-card { width: min(100%, 414px); padding: 24.75px 18px 27px; }
  .login-page .login-card .login-logo { width: min(180px, 100%); height: 136px; margin-bottom: 18px; }
  .login-page .login-card h1 { margin-bottom: 35px; }
  .login-page .login-card input { min-height: 44px; }
  .login-page .login-card .login-submit { min-height: 48px; }
}

/* Ícone nativo de mostrar senha no Edge: contraste branco no campo escuro. */
.login-page #login-password::-ms-reveal,
.login-page #login-password::-ms-clear {
  filter: invert(1);
}
